GpibEngine::GpibEngine()
    : mailbox_(0), ownedDriver_(0), up_(false), started_(false), closed_(false), depth_(0), lastUiMs_(0)
{
}

GpibEngine::~GpibEngine()
{
    // Normal path: Stop() already ran on the TesterComm thread.  If Start() succeeded but Stop() never ran (the
    // thread died), the TesterComm thread is gone by the time the hub deletes us, so tearing down here is safe.
    if (started_)
        Teardown();
}

bool GpibEngine::Start(testercomm::SyncMailbox* mailbox)
{
    if (mailbox == 0 || started_)
        return false;
    int expected = 0;
    if (!g_live.compare_exchange_strong(expected, 1))
        return false;   // another GpibEngine is alive (golden: CreateMutex "MyMutexGPIB" refused a 2nd bridge)

    mailbox_ = mailbox;
    started_ = true;
    closed_ = false;
    depth_ = 0;

    IGpibDriver* d = g_injected.load();
    if (d == 0)
    {
        NiGpibDriver* ni = new NiGpibDriver;
        if (ni->Loaded())
        {
            d = ni;
            ownedDriver_ = ni;
        }
        else
        {
            delete ni;   // no NI-488.2 runtime: golden's ibfind fails and it logs "Error Open GPIB0"
        }
    }
    SetGpibDriver(d);

    // golden: every life is a fresh process -- globals at their initialisers, function-local statics re-armed
    // (GpibBridge.h "V906 bridge life").  Must precede the TSerialPoll ctor, which golden runs on fresh globals.
    ResetBridgeGlobals();
    ++g_bridgeLife;
    if (!g_genIniOverride.empty())
        asGeneralPath = g_genIniOverride.c_str();
    if (!g_hgenIniOverride.empty())
        asHGeneralPath = g_hgenIniOverride.c_str();

    // golden FindWindow("TfMain", "HT-9045") -> HMountWnd: the Handler side is "found" while the mailbox exists.
    HMountWnd = reinterpret_cast<HWND>(mailbox);
    g_handlerTok.store(static_cast<void*>(mailbox));

    try
    {
        // golden WinMain order (H9046_32GPIB.cpp): CreateForm(SerialPoll) [OnCreate], CreateForm(fDummyART),
        // CreateForm(fRS232Main), Application->Run [main form OnShow].  fMyPal is golden's design-time template
        // form for TMyDutPanel and has no runtime role here.
        VclCreateForm(SerialPoll);
        SerialPoll->mailbox = mailbox;
        g_bridgeTok.store(static_cast<void*>(SerialPoll));
        SerialPoll->FormCreate(0);
        VclCreateForm(fDummyART);
        VclCreateForm(fRS232Main);
        SerialPoll->FormShow(0);
    }
    catch (...)
    {
        Teardown();
        return false;
    }

    timer1_ = TimerSlot();
    timerTMode_ = TimerSlot();
    timerDummyArt_ = TimerSlot();
    up_.store(!SerialPoll->closeRequested);
    return true;
}

void GpibEngine::DoClose()
{
    if (closed_ || SerialPoll == 0)
        return;
    closed_ = true;
    up_.store(false);
    // golden Close() -> OnClose = FormClose (Main.dfm:152): log, SaveResult, WriteLastDataFile, WriteGpibString.
    SerialPoll->FormClose(0);
    testercomm::UiChannel::Instance().Publish(kUiKey, BuildUiSnapshot(false, "closed"));
    testercomm::UiChannel::Instance().Publish("gpib.home", BuildHomeFragment(false));   // AI(W906-TC-SHARED) 20261001 (St02-E)
}

void GpibEngine::Stop()
{
    if (!started_)
        return;
    if (!closed_)
        DoClose();   // golden: Handler's CloseGpibProgram -> MSG_CMD_CloseGpib -> Close() -> FormClose
    Teardown();
}

void GpibEngine::Teardown()
{
    up_.store(false);
    // fRS232Main first: its CommTester reader thread queues into SerialPoll.
    delete fRS232Main;
    fRS232Main = 0;
    delete fDummyART;
    fDummyART = 0;
    g_bridgeTok.store(0);
    delete SerialPoll;   // stops CommAMD / CommAMD2
    SerialPoll = 0;
    testercomm::UiChannel::Instance().Publish(kUiKey, "{\"up\":false}");
    g_handlerTok.store(0);
    HMountWnd = 0;
    GHandler2Gpib = 0;
    SetGpibDriver(0);
    delete ownedDriver_;
    ownedDriver_ = 0;
    mailbox_ = 0;
    started_ = false;
    g_live.store(0);
}

class GpibEngine : public testercomm::TesterEngine
{
public:
    GpibEngine();
    ~GpibEngine();

    const char* Name() const { return "gpib"; }
    bool Start(testercomm::SyncMailbox* mailbox);
    unsigned RunOnce();
    int OnHandlerMessage(const std::string& payload);
    void Stop();
    bool IsUp() const { return up_.load(); }

    // ctest / SOFT_SIMULTE: use this driver instead of gpib-32.dll (not owned; must outlive the engine).
    // Call before the hub starts the engine.
    static void InjectDriver(IGpibDriver* driver);

    // ctest: point golden's two ini path variables (asGeneralPath / asHGeneralPath) elsewhere.  Applied at every
    // Start() after ResetBridgeGlobals(); empty = golden paths.  Call before the hub starts the engine.  Golden's
    // literal paths (D:\GPIBLOG, D:\RS232Standard\System\Setup.ini, ...) are not affected.
    static void OverrideIniPaths(const std::string& generalIni, const std::string& handlerGeneralIni);

    // Factory for TesterCommHub::RegisterFactory(kTestTypeGpib, ...).
    static testercomm::TesterEngine* Create();

    // Identity tokens for golden's window-handle checks (OnMyCopyMsg compares GHandler2Gpib->HandlerHwnd with
    // HMountWnd and GHandler2Gpib->GpibHwnd with this->Handle).  The Handler side (P2) fills MV.HandlerHwnd /
    // MV.GpibHwnd with these.  NULL while no bridge is running.  Readable from any thread.
    static HWND HandlerWndToken();
    static HWND BridgeWndToken();

    // Diagnostics (any thread).
    static unsigned long PostFailures();    // PostToHandler sends that timed out / had no receiver
    static unsigned long HandlerMessages(); // OnMyCopyMsg calls

    // VCL TTimer emulation (public for ctest).  Due() is true when the timer should fire now: Enabled, and
    // Interval ms elapsed since the last fire or since the false->true Enabled edge.  Interval 0 never fires; missed
    // periods are not caught up (WM_TIMER coalesces).
    struct TimerSlot
    {
        bool wasEnabled;
        unsigned long long lastMs;
        TimerSlot() : wasEnabled(false), lastMs(0) {}
    };
    static bool Due(TimerSlot& slot, bool enabled, unsigned interval, unsigned long long nowMs);

private:
    GpibEngine(const GpibEngine&);
    GpibEngine& operator=(const GpibEngine&);

    void DoClose();              // golden OnClose, once
    void Teardown();             // delete the forms, release the driver

    testercomm::SyncMailbox* mailbox_;
    IGpibDriver* ownedDriver_;   // NiGpibDriver we created (deleted in Teardown)
    std::atomic<bool> up_;
    bool started_;
    bool closed_;                // FormClose done
    int depth_;                  // nesting of OnHandlerMessage (mailbox pump); DoClose only at depth 0
    TimerSlot timer1_, timerTMode_, timerDummyArt_;
    unsigned long long lastUiMs_;   // P7: last UiChannel snapshot (every kUiPeriodMs)
};
